from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer
from reportlab.lib.units import cm
from reportlab.lib import colors
import os

OUTPUT_DIR = os.path.join(os.path.dirname(os.path.dirname(__file__)), "data", "pdfs")
os.makedirs(OUTPUT_DIR, exist_ok=True)

DOCUMENTS = [('01_billing_invoices.pdf', 'Billing and Payments', 'Understanding CloudDesk Invoices', [('Purpose', 'This guide explains how CloudDesk customers can find, read, and download invoices for their organization.'), ('Where to find invoices', 'An organization owner or billing administrator can open Settings, choose Billing, and select Invoices. The invoice list shows the invoice number, issue date, billing period, amount, currency, and payment status. Users without the billing permission may not see this section.'), ('Invoice status definitions', 'Paid means the payment was confirmed. Open means payment is still due. Past due means the due date has passed without a confirmed payment. Voided means the invoice was cancelled and should not be paid. A pending payment may take time to be reflected after the payment provider confirms it.'), ('Downloading an invoice', 'Open Settings > Billing > Invoices, select the required invoice, and choose Download PDF. If the button is unavailable, check that the user has billing permission and refresh the page. If the invoice still cannot be downloaded, contact support with the invoice number and organization name.'), ('Invoice details and corrections', 'Invoices include the legal organization name, billing address, tax details when applicable, line items, subtotal, taxes, credits, and total. Only a billing administrator can update billing profile details. Changes to profile details do not automatically rewrite a previously issued invoice. For a correction to an issued invoice, contact the billing team and provide the invoice number plus the exact field that needs correction.'), ('Example', 'If invoice CD-1042 is marked Open, the customer should first check the due date and payment method. If the customer already paid, ask for the payment confirmation reference instead of advising them to pay twice.')]), ('02_failed_payments.pdf', 'Billing and Payments', 'Troubleshooting Failed Payments', [('Common causes', "A payment can fail because the card expired, the bank declined the transaction, the billing address does not match, the card has insufficient funds, or the payment provider requires additional authentication. CloudDesk support cannot see a customer's full card number."), ('Recommended checks', "Ask the billing administrator to open Settings > Billing > Payment methods and confirm that the saved method is current. Check the bank's notification for a decline reason. If authentication is requested, complete it through the secure payment flow rather than sending card information by email."), ('Retrying a payment', 'If the invoice is still Open or Past due, the billing administrator can open the invoice and select Retry payment when that option is available. Do not repeatedly retry a payment that the bank has explicitly blocked. Resolve the bank or payment-method issue first.'), ('Pending transactions', "A pending bank transaction does not always mean CloudDesk received the payment. Ask the customer to wait for the payment provider's final status and share a transaction reference if the invoice remains unpaid. Avoid promising an exact settlement time because bank processing varies."), ('Security', 'Never ask customers to send full card numbers, CVV codes, passwords, or one-time authentication codes to support. If a customer has already sent sensitive payment information, do not repeat it in a reply; direct them to their bank or payment provider as appropriate.'), ('Escalation', "Escalate to Billing Operations if the provider reports a successful charge but the invoice remains unpaid after the provider's status is final. Include organization name, invoice number, transaction reference, and timestamps. Do not include full payment credentials.")]), ('03_payment_methods.pdf', 'Billing and Payments', 'Managing Payment Methods', [('Who can manage payment methods', 'Only an organization owner or billing administrator can add, update, or remove payment methods. A regular member should ask an authorized administrator to make billing changes.'), ('Add a payment method', 'Go to Settings > Billing > Payment methods, select Add payment method, and complete the secure payment form. Save the method and verify that it appears in the list. Payment credentials are handled by the payment provider.'), ('Update an expired card', 'Choose the existing method, select Edit or Replace when available, and enter the updated details in the secure form. If editing is not available, add the new method and set it as the default before removing the old one.'), ('Default method', 'The default payment method is used for eligible automatic renewals and invoices. After changing the default, confirm that the correct method is labelled Default. Updating a method does not necessarily retry an invoice that already failed.'), ('Removing a method', 'A method may not be removable if it is the only valid method for an active subscription or an unpaid invoice requires it. Add a replacement and resolve outstanding billing requirements first.'), ('Support boundaries', 'Support cannot enter payment details on behalf of customers, collect card credentials by email, or guarantee that a bank will authorize a transaction.')]), ('04_taxes_and_billing_profiles.pdf', 'Billing and Payments', 'Tax Details and Billing Profiles', [('Billing profile', 'The billing profile contains the legal organization name, billing address, and tax identification details supplied by the customer. Billing administrators can review and update the profile in Settings > Billing > Billing profile.'), ('Tax calculation', "Taxes may depend on the customer's location, supplied tax details, and applicable rules. Support should explain where profile information is managed but must not invent a tax rate or provide a definitive tax determination when the account-specific facts are unavailable."), ('Updating tax information', 'Enter accurate information in the billing profile and save the changes. If a tax identifier is rejected, verify the country and formatting, then contact Billing Operations with the organization name and the displayed error. Do not ask the customer to post sensitive tax documents in a public channel.'), ('Previously issued invoices', 'A profile update generally applies to future billing documents. It does not automatically amend an already issued invoice. For a historical invoice correction, request review by Billing Operations and identify the invoice number and requested correction.'), ('Currency and totals', 'The invoice displays the currency used for that billing transaction. Support must refer to the currency shown on the invoice and should not estimate foreign-exchange conversion amounts.'), ('Example', 'A customer updates the company address on 12 May and asks why an invoice issued on 3 May still shows the old address. Explain that profile updates do not automatically rewrite previously issued invoices and offer a Billing Operations review.')]), ('05_subscription_plans.pdf', 'Subscriptions and Refunds', 'Plans, Upgrades, and Downgrades', [('Plan overview', "CloudDesk subscriptions have plan-specific limits and features. The account's Billing page is the authoritative place to view the current plan, renewal date, and available changes."), ('Upgrade', 'An owner or billing administrator can open Settings > Billing > Plan, compare available plans, and select Upgrade. The confirmation screen shows any price or proration information before the change is confirmed. Customers should review that screen before accepting.'), ('Downgrade', 'A downgrade may reduce feature access or usage limits. Review the plan comparison and any effective date shown during the change flow. Do not promise a specific effective date unless the account screen confirms it.'), ('Permissions', 'Members without billing permissions may be able to use the product but cannot change the subscription. They should ask the organization owner or billing administrator.'), ('Failed plan change', 'If a plan change fails, record the displayed error, current plan, intended plan, and organization name. Check whether the account has an unresolved payment or permission issue before escalating.'), ('Support guidance', "Never invent prices, discounts, or plan limits. Use the customer's current Billing page or approved pricing documentation. If those details are not available in the support knowledge base, state that the account-specific information needs checking.")]), ('06_cancellations.pdf', 'Subscriptions and Refunds', 'Cancelling a CloudDesk Subscription', [('Who can cancel', 'An organization owner or billing administrator can manage cancellation from Settings > Billing > Plan. Other members should contact an authorized administrator.'), ('Cancellation steps', 'Open Settings > Billing > Plan, choose Cancel subscription, review the confirmation screen for the effective date and access consequences, and confirm only if the details are correct. Save or note the confirmation displayed by the product.'), ('Access after cancellation', 'The cancellation screen states when paid access ends and whether any remaining access continues through the current billing period. The actual account confirmation is authoritative; support should not promise a date without seeing it.'), ('Before cancelling', 'Customers may export needed data and review which features will become unavailable. Support must not claim that cancellation automatically deletes an organization or all stored data unless the applicable policy explicitly says so.'), ('Unexpected renewal', 'If a customer reports a renewal after cancellation, request the organization name, invoice number, cancellation confirmation, and relevant dates. Escalate to Billing Operations for review.'), ('Retention and refunds', 'Cancellation and refund eligibility are separate questions. Do not tell a customer that cancellation automatically guarantees a refund. Refer to the refund policy and the details shown on the account.')]), ('07_refund_policy.pdf', 'Subscriptions and Refunds', 'Refund Eligibility and Requests', [('General rule', 'Refunds are reviewed individually by Billing Operations. A refund is not automatic merely because a subscription was cancelled or a customer did not use the service.'), ('How to request review', 'Collect the organization name, invoice number, payment date, amount and currency shown on the invoice, reason for the request, and any cancellation confirmation. Route the request to Billing Operations; do not promise approval or a processing date.'), ('Duplicate charges', 'If a customer reports two charges, ask for the invoice numbers or payment references and the dates. Do not conclude that a duplicate charge occurred based only on a pending bank authorization. Escalate confirmed or unresolved cases to Billing Operations.'), ('Refund status', 'If a refund has been approved, share only the status available in the billing system. Bank posting times can vary, so do not promise an exact date unless an approved policy provides one.'), ('Non-refundable assumptions', 'This guide does not define universal refund windows or guarantee refunds for any particular reason. If the customer asks about a deadline or exception not stated here, say that Billing Operations must confirm the applicable terms.'), ('Example response', '“I can send your request to our Billing Operations team for review. Please share the invoice number and a brief explanation of the charge. I cannot promise an outcome before the review is complete.”')]), ('08_password_reset.pdf', 'Login and Account Security', 'Resetting a Forgotten Password', [('Password reset', 'On the CloudDesk sign-in page, select Forgot password, enter the email address associated with the account, and follow the instructions sent to that inbox.'), ('Email not received', "Check spam or junk folders, confirm that the address was entered correctly, and wait a short period before requesting another message. If the account uses single sign-on, the user may need to reset the password through the organization's identity provider instead."), ('Expired reset link', 'A reset link may expire or become invalid after a newer request. Start again from Forgot password and use the newest message. Do not forward reset links to support.'), ('Security practices', "Support will never ask for the user's password or one-time code. Do not ask customers to email passwords. If the user suspects account compromise, follow the suspicious-login procedure."), ('Account not found', 'A message that does not identify an account may be used to protect account privacy. Ask the user to verify the sign-in email and organization rather than confirming private account information through an unverified channel.'), ('Escalation', 'If reset messages still do not arrive after the basic checks, collect the sign-in email, approximate request time, organization, and whether the account uses SSO. Avoid collecting passwords or authentication codes.')]), ('09_mfa_and_sso.pdf', 'Login and Account Security', 'Multi-Factor Authentication and Single Sign-On', [('MFA basics', 'Multi-factor authentication adds a verification step beyond a password. Users should keep recovery options current and store backup codes securely if the product provides them.'), ('Lost device', "If a user loses access to their authenticator, use the official recovery option provided by CloudDesk or the organization's identity provider. Support must not bypass identity verification or accept a one-time code as proof of identity."), ('SSO accounts', "When an organization enforces single sign-on, users generally authenticate through the organization's identity provider. Password resets and MFA changes may need to be completed there."), ('Troubleshooting', 'Confirm the correct organization sign-in page, system clock, browser, and identity-provider status. Capture the exact error and timestamp if the issue persists. Do not ask the user to disable security protections as a routine workaround.'), ('Administrator role', "An organization administrator may manage SSO configuration if permitted, but should follow the organization's approved identity process. Support should escalate configuration changes that could lock out multiple users."), ('Security incident', 'If the customer reports an unknown sign-in or suspected compromise, follow the suspicious-login guide and prioritize securing the account.')]), ('10_suspicious_login.pdf', 'Login and Account Security', 'Responding to Suspicious Login Activity', [('Recognize the issue', 'Examples include sign-in notifications the user does not recognize, unexpected password-reset emails, unfamiliar sessions, or changes the user did not make.'), ('Immediate actions', "Use the official CloudDesk security settings to review sessions and sign out unfamiliar sessions if that control is available. Change the password through the trusted sign-in flow and review MFA and recovery settings. For SSO accounts, contact the organization's identity administrator."), ('Do not share secrets', 'Never ask the customer to provide their password, MFA code, recovery code, or full payment credentials. Do not copy secrets into ticket notes.'), ('Report details', 'Record the account email, organization, approximate event time, notification details, and any actions already taken. Ask the customer to redact unrelated personal information from screenshots.'), ('Escalation', 'Escalate suspected compromise to the Security team promptly using the internal incident process. Do not assure the customer that the account is safe until the security review supports that statement.'), ('Customer communication', 'Acknowledge the concern, give the immediate safe steps, and explain that the issue is being reviewed. Avoid speculation about who accessed the account or how.')]), ('11_user_invitations.pdf', 'Account Administration', 'Inviting and Removing Organization Members', [('Invite a member', 'An owner or administrator with user-management permission can open Settings > Members, choose Invite member, enter the work email, assign the appropriate role, and send the invitation.'), ('Invitation status', 'Pending means the invite has not yet been accepted. Accepted means the member completed the invitation flow. If an invite expires or is revoked, an administrator can issue a new invitation when the interface permits it.'), ('Invite not received', 'Verify the address, ask the recipient to check spam, and confirm that the invitation is still pending. If the invite cannot be resent or the status is inconsistent, capture the organization and email and contact support.'), ('Least privilege', "Assign the minimum role needed for the person's work. Do not grant administrator access merely to solve a routine login or access problem."), ('Removing a member', 'An authorized administrator can select the member in Settings > Members and choose Remove when available. Before removal, consider ownership of active work and any organizational offboarding procedure.'), ('Privacy', 'Do not confirm whether an email belongs to another organization to an unverified requester. Verify authority before disclosing membership details.')]), ('12_roles_permissions.pdf', 'Account Administration', 'Roles and Permissions Guide', [('Role principle', "Roles determine which areas and actions a user can access. CloudDesk may offer owner, administrator, and member roles, with permissions depending on the organization's configuration."), ('Owner', 'The owner is responsible for core organization administration and billing authority. Ownership transfer should follow the approved account-verification process.'), ('Administrator', 'Administrators can manage permitted organization settings and users. Billing access may depend on the assigned permissions and plan configuration.'), ('Member', 'Members can use features granted to them but generally cannot change organization-wide billing or security settings unless explicitly permitted.'), ('Access denied', "Check the user's organization, assigned role, and the specific action that failed. Ask an authorized administrator to confirm permissions. Do not recommend sharing another user's login."), ('Escalation details', "If the role appears correct but access remains denied, collect the user's role, organization, affected page or action, timestamp, and exact error. Do not include passwords or authentication codes.")]), ('13_organization_settings.pdf', 'Account Administration', 'Managing Organization Settings', [('Settings access', 'Organization settings are available to authorized owners or administrators. The options shown may depend on the plan and assigned permissions.'), ('Organization profile', 'Authorized users can review the organization name and profile fields in Settings. Before changing a shared name or domain, confirm that the change is intended for the whole organization.'), ('Domain changes', 'If the organization needs to change a verified email domain or domain-based sign-in setting, use the approved verification process. Do not treat possession of an email address alone as sufficient proof of domain ownership.'), ('Ownership changes', 'Ownership transfers can affect billing, access, and administrative responsibility. Follow the documented identity-verification and approval procedure rather than changing ownership based only on a ticket request.'), ('Settings not visible', "If a setting is missing, check the user's role, current plan, and organization context. If the documentation does not explain the setting, escalate with a screenshot that excludes sensitive information."), ('Safe change practice', "Record the requested change, the authorized requester, and the confirmation shown by the product. For security-sensitive changes, follow the organization's approval process.")]), ('14_email_notifications.pdf', 'Troubleshooting', 'Troubleshooting Missing Email Notifications', [('Initial checks', "Confirm the email address, check spam and junk folders, inspect notification preferences, and verify whether the message appears in the product's notification center if one exists."), ('Notification preferences', 'Users may control some notification types in Settings > Notifications. Organization policies or administrator settings may affect which options are available.'), ('Delivery delays', 'Email delivery can be delayed by recipient mail systems, filtering, or provider issues. Do not promise a precise delivery time without evidence.'), ('Administrator checks', 'For organization-wide delivery problems, ask the administrator whether mail filters, allowlists, or domain policies recently changed. Do not ask the customer to weaken security controls globally.'), ('Information for support', 'Collect the recipient address, message type, approximate send time, organization, and whether other recipients are affected. Never request email account passwords.'), ('Escalation', 'If several users are affected or logs indicate a delivery failure, route the case to the messaging or engineering team with the collected timestamps and message identifiers, if available.')]), ('15_dashboard_errors.pdf', 'Troubleshooting', 'Resolving Dashboard Loading Errors', [('Basic checks', "Refresh the page, confirm the network connection, sign out and back in if safe, and try a supported browser with extensions temporarily disabled only when permitted by the user's security policy."), ('Scope the issue', 'Determine whether the problem affects one user, one browser, one organization, or multiple users. Ask for the page, approximate time, and exact error text.'), ('Browser troubleshooting', 'If appropriate, test a private window or clear site data for CloudDesk only. Explain that clearing site data may sign the user out. Do not ask the user to share session cookies or authentication tokens.'), ('Service-wide issue', 'If multiple users report the same failure, check the official status channel or internal incident process before recommending repeated local troubleshooting.'), ('Evidence', 'A screenshot of the error can help, but it should not expose private customer data, tokens, or unrelated browser tabs. Capture a request or correlation ID if the application displays one.'), ('Escalation', 'If the issue persists, send the reproduction steps, browser and operating-system versions, time of failure, affected organization, and error details to support engineering.')]), ('16_file_uploads.pdf', 'Troubleshooting', 'Troubleshooting File Upload Failures', [('Before retrying', 'Check the file type and size against the upload limits shown in the CloudDesk interface. This guide does not define a universal size limit; use the current product message or approved documentation.'), ('File name and format', 'Try a simple file name and a supported format. If the file is damaged or incomplete, create a valid copy and retry. Do not rename a file to a different extension as a substitute for converting its format.'), ('Network and browser', 'Check the connection and retry once. If appropriate, test another supported browser. Avoid repeated large uploads when the error suggests a server-side problem.'), ('Sensitive documents', 'Upload only information required for the support case and use approved secure channels. Do not request passwords, payment card security codes, or unnecessary personal documents.'), ('Evidence to collect', 'Record the file type, approximate size, time, organization, exact error, and whether other files fail. Do not attach confidential files to an internal ticket unless the process authorizes it.'), ('Escalation', 'Escalate repeated failures with the error text and reproduction steps. If the product displays a request ID, include it.')]), ('17_ticket_priorities_escalation.pdf', 'Support Procedures', 'Ticket Priorities and Escalation', [('Priority principles', "Priority is based on impact and urgency, not on the customer's tone alone. A widespread outage or security incident generally needs faster attention than a single-user how-to question."), ('P1 critical', 'Use P1 for a confirmed or strongly evidenced critical service outage or severe security incident with broad impact. Notify the on-call or incident channel according to the internal process.'), ('P2 high', 'Use P2 for major functionality unavailable to a group of users or a business-critical workflow with no reasonable workaround.'), ('P3 normal', 'Use P3 for a limited-impact problem, a single-user issue with a workaround, or a standard product question.'), ('P4 low', 'Use P4 for cosmetic issues, minor requests, or general feedback that does not block work.'), ('Escalation payload', 'Include customer impact, affected users, start time, reproduction steps, error text, attempted troubleshooting, and any request ID. Do not claim an incident is confirmed unless evidence supports it.'), ('Priority uncertainty', "If impact is unclear, ask concise questions and follow the team's triage policy. Escalate suspected security incidents promptly even while details are being gathered.")]), ('18_support_response_times.pdf', 'Support Procedures', 'Support Response Times and Case Updates', [('General approach', 'Give customers realistic updates based on the support policy and the current ticket state. A response target is not the same as a guaranteed resolution time.'), ('No invented SLA', "This fictional knowledge base does not specify contractual response-time numbers. If a customer asks for an exact SLA or resolution deadline, check the customer's agreement or approved support policy rather than inventing a number."), ('Acknowledgement', 'Acknowledge the issue, summarize the impact, and explain the next action. If investigation is ongoing, say what is being checked and when the next update is expected only when that update time is known.'), ('Waiting on customer', "Ask for the specific missing information needed to proceed. Avoid closing a case without following the team's documented waiting and closure process."), ('Escalated cases', 'Tell the customer that the case has been referred to the relevant team when that is true. Do not expose internal-only notes, private employee details, or speculative root causes.'), ('Example', '“We are investigating the upload error using the details you provided. We will update you when we have a verified finding. I cannot confirm a resolution time yet.”')]), ('19_customer_reply_style.pdf', 'Communication Guidelines', 'Writing Clear and Helpful Customer Replies', [('Tone', "Be calm, respectful, concise, and specific. Acknowledge the customer's problem without blaming the customer or making unsupported promises."), ('Recommended structure', 'A useful reply usually contains: acknowledgement, verified explanation, numbered next steps, any information needed from the customer, and the next action support will take.'), ('Plain language', 'Prefer common words and short sentences. Explain technical terms when they are necessary. Avoid internal acronyms unless the customer already uses them.'), ('Accuracy', 'Distinguish confirmed facts from possibilities. Do not invent product behavior, policy exceptions, refund outcomes, prices, or deadlines. If evidence is missing, say what needs to be checked.'), ('Privacy and security', 'Never request passwords, MFA codes, CVV codes, or session tokens. Ask for only the information needed to investigate and use approved secure channels.'), ('Example', 'Instead of “This is not our issue,” write: “I understand this is blocking your work. I’ll check whether the error is related to your account settings or a wider service issue, and I’ll let you know what I find.”')]), ('20_complaints_and_deescalation.pdf', 'Communication Guidelines', 'Handling Complaints and Frustrated Customers', [('Start with acknowledgement', "Recognize the customer's experience without arguing about their emotions. For example: “I can see why a repeated payment error is frustrating.”"), ('Clarify the impact', 'Ask one or two focused questions about what is blocked, who is affected, and when the issue started. Avoid making the customer repeat information already in the ticket.'), ('Explain the plan', 'State the next action and what information is needed. If another team must investigate, explain the handoff in plain language without exposing internal-only details.'), ('Avoid harmful promises', 'Do not guarantee a refund, a fix, a delivery time, or a policy exception before it is confirmed. Do not speculate about fault or blame another team.'), ('When to escalate', 'Escalate threats, suspected security incidents, broad outages, legal concerns, or repeated unresolved failures according to the applicable internal process.'), ('Example reply', '“I’m sorry this has taken more effort than expected. I’ve summarized the steps you already tried so you won’t need to repeat them. I’ll route the remaining issue for review and share an update when I have verified information.”')])]

styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="DocTitle", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=20, leading=24, alignment=TA_CENTER, textColor=colors.HexColor("#183153"), spaceAfter=14))
styles.add(ParagraphStyle(name="Category", parent=styles["Normal"], fontSize=10, leading=14, alignment=TA_CENTER, textColor=colors.HexColor("#4B5563"), spaceAfter=18))
styles.add(ParagraphStyle(name="SectionHead", parent=styles["Heading2"], fontSize=12, leading=15, textColor=colors.HexColor("#1D4ED8"), spaceBefore=10, spaceAfter=5))
styles.add(ParagraphStyle(name="BodyTextCustom", parent=styles["BodyText"], fontSize=9.5, leading=14, spaceAfter=7))

def escape_text(value):
    return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

for filename, category, title, sections in DOCUMENTS:
    path = os.path.join(OUTPUT_DIR, filename)
    story = [
        Spacer(1, 0.8 * cm),
        Paragraph(escape_text("CloudDesk Support Knowledge Base"), styles["Category"]),
        Paragraph(escape_text(title), styles["DocTitle"]),
        Paragraph(escape_text(category), styles["Category"]),
        Paragraph(escape_text("Fictional training documentation for a local RAG demonstration."), styles["BodyTextCustom"]),
        Spacer(1, 0.25 * cm),
    ]
    for heading, body in sections:
        story.append(Paragraph(escape_text(heading), styles["SectionHead"]))
        story.append(Paragraph(escape_text(body), styles["BodyTextCustom"]))
    story.append(Spacer(1, 0.4 * cm))
    story.append(Paragraph(escape_text("Document owner: CloudDesk Support Operations | Version: 1.0"), styles["Category"]))
    pdf = SimpleDocTemplate(
        path, pagesize=A4, rightMargin=1.8 * cm, leftMargin=1.8 * cm,
        topMargin=1.6 * cm, bottomMargin=1.6 * cm, title=title,
        author="CloudDesk Support Operations"
    )
    pdf.build(story)

print(f"Generated {len(DOCUMENTS)} PDFs in: {OUTPUT_DIR}")
